package rubytools // import "go.opentelemetry.io/obi/pkg/internal/rubytools"

import (
	"bufio"
	"regexp"
	"strings"

	"go.opentelemetry.io/obi/pkg/internal/langtools"
)

const maxRailsApplicationBytes int64 = 64 * 1024

var (
	acronymBoundary = regexp.MustCompile(`([A-Z\d]+)([A-Z][a-z])`)
	wordBoundary    = regexp.MustCompile(`([a-z\d])([A-Z])`)

	railsModuleDeclaration = regexp.MustCompile(
		`^\s*module\s+(?:::)?([A-Z][A-Za-z\d_]*(?:::[A-Z][A-Za-z\d_]*)*)\s*(?:#.*)?$`,
	)
	railsApplicationDeclaration = regexp.MustCompile(
		`^\s*class\s+((?:::)?[A-Z][A-Za-z\d_]*(?:::[A-Z][A-Za-z\d_]*)*)\s*<\s*(?:::)?Rails::Application\b`,
	)
	rubyScopeDeclaration = regexp.MustCompile(
		`^(?:class|def|if|unless|case|while|until|for|begin)\b`,
	)
	rubyDoBlockDeclaration = regexp.MustCompile(
		`\bdo(?:\s*\|[^|]*\|)?\s*(?:#.*)?$`,
	)
	rubyScopeEnd = regexp.MustCompile(`^end(?:\s*#.*)?$`)
)

type rubyScope struct {
	moduleName string
}

func readRailsApplicationName(path string) string {
	file, _ := langtools.OpenMetadataFile(path, maxRailsApplicationBytes)
	if file == nil {
		return ""
	}
	defer file.Close()

	return scanRailsApplicationName(bufio.NewScanner(file))
}

// scanRailsApplicationName recognizes the conventional declaration generated by Rails. It is
// intentionally a heuristic: unusual Ruby metaprogramming falls back to the project directory.
func scanRailsApplicationName(scanner *bufio.Scanner) string {
	var scopes []rubyScope
	var applicationName string
	applicationDeclarations := 0

	for scanner.Scan() {
		line := scanner.Text()
		if match := railsModuleDeclaration.FindStringSubmatch(line); match != nil {
			if applicationDeclarations == 0 && hasRubyModuleScope(scopes) {
				return ""
			}
			scopes = append(scopes, rubyScope{moduleName: match[1]})
			continue
		}

		match := railsApplicationDeclaration.FindStringSubmatch(line)
		if match != nil {
			applicationDeclarations++
			if applicationDeclarations == 1 {
				applicationName = railsApplicationName(match[1], scopes)
			}
		}

		scopes = updateRubyScopes(scopes, line)
	}

	if scanner.Err() != nil || applicationDeclarations != 1 {
		return ""
	}
	return applicationName
}

func hasRubyModuleScope(scopes []rubyScope) bool {
	for _, scope := range scopes {
		if scope.moduleName != "" {
			return true
		}
	}
	return false
}

func railsApplicationName(class string, scopes []rubyScope) string {
	class = strings.TrimPrefix(class, "::")
	if class != "Application" {
		for _, scope := range scopes {
			if scope.moduleName == "" {
				return ""
			}
		}
		return railsServiceName(class)
	}

	if len(scopes) != 1 {
		return ""
	}
	return railsServiceName(scopes[0].moduleName)
}

func updateRubyScopes(scopes []rubyScope, line string) []rubyScope {
	line = strings.TrimSpace(line)
	if line == "" || strings.HasPrefix(line, "#") {
		return scopes
	}

	if rubyScopeEnd.MatchString(line) {
		if len(scopes) == 0 {
			return scopes
		}
		return scopes[:len(scopes)-1]
	}

	if rubyScopeDeclaration.MatchString(line) || rubyDoBlockDeclaration.MatchString(line) {
		return append(scopes, rubyScope{})
	}
	return scopes
}

func railsServiceName(className string) string {
	if className == "" {
		return ""
	}

	className = strings.TrimSuffix(className, "::Application")
	parts := strings.Split(className, "::")
	for index, part := range parts {
		part = acronymBoundary.ReplaceAllString(part, `${1}_${2}`)
		part = wordBoundary.ReplaceAllString(part, `${1}_${2}`)
		part = strings.ReplaceAll(part, "_", "-")
		parts[index] = strings.ToLower(part)
	}

	return strings.Join(parts, "/")
}
